with with_windows as (select id, amount, txn_time, merchant, count(amount) over w_running as running_count_amount, max(amount) over w_running as running_max_amount, min(amount) over w_running as running_min_amount from transactions window w_running as (partition by merchant order by txn_time, id rows between unbounded preceding and current row)) select id, amount, txn_time, running_count_amount, running_max_amount, running_min_amount from with_windows
